//! Names a receiver saves a batch's files under: two files of a batch never get names the receiving storage
//! could take for one file, and the later one of two such names gets " (2)" (" (3)", ...) before its extension.
//!
//! When storage takes two names for one file: NTFS, Android's shared storage and macOS ignore case; macOS
//! keeps names decomposed (NFD), so the same name typed on two systems can arrive as different code points;
//! Android's media store drops a leading dot. `name_key` maps a name to what all of these see: its canonical
//! decomposition, case folded, with leading dots dropped. Two names with one key are kept apart, which is the
//! safe side: a key that is too coarse only renames a file that would have been fine, while one too fine lets a
//! file overwrite another.
//!
//! No crate for Unicode normalisation is in the dependency tree, and the core keeps its dependencies few (it
//! is built for WebAssembly and Android too), so this module carries what it needs:
//! - every canonical decomposition of the Basic Multilingual Plane (`DECOMPOSITIONS`, generated from Unicode
//!   16.0's data), except the Hangul syllables, which are decomposed by formula, and the CJK compatibility
//!   ideographs (U+F900 to U+FAFF), which name storage leaves alone in practice; Latin, Greek, Cyrillic, kana
//!   with voicing marks and Korean are all covered;
//! - the canonical combining classes of the plane (`COMBINING_CLASSES`), to put the marks after a letter in
//!   canonical order (`ê` + dot below and `e` + dot below + circumflex are one name);
//! - case folding from the standard library: lowercase, uppercase, lowercase again, which folds `ß` and `ẞ`
//!   to "ss", final sigma to sigma and `ﬁ` to "fi", as full case folding does.
//!
//! Characters outside the plane pass unchanged (emoji, historic scripts); a supplementary character with a
//! canonical decomposition is rare in a file name. About 8 KB of tables.
use super::batch::MAX_NAME_BYTES;
use std::collections::{HashMap, HashSet};

/// What a name is to the storage that receives it (see the module comment): equal keys, one file.
pub fn name_key(name: &str) -> String {
    let name = name.trim_start_matches('.');
    if name.is_ascii() { return name.to_ascii_lowercase(); }
    let mut d = Vec::with_capacity(name.len());
    for c in name.chars() { decompose(c, &mut d); }
    let mut folded = Vec::with_capacity(d.len());
    for c in d {
        for l in c.to_lowercase() { for u in l.to_uppercase() { for f in u.to_lowercase() { decompose(f, &mut folded); } } }
    }
    reorder(&mut folded);
    folded.into_iter().collect()
}

/// `name` with " (n)" before its extension, in at most 255 bytes: the stem is cut (at a character boundary)
/// to make room. The extension is the last `.` and what follows, after a non-empty stem; one too long to leave
/// room for a stem is treated as part of the stem.
pub fn with_suffix(name: &str, n: u32) -> String {
    let tag = format!(" ({n})");
    let (mut stem, mut ext) = match name.rfind('.') { Some(i) if i > 0 => name.split_at(i), _ => (name, "") };
    if ext.len() + tag.len() >= MAX_NAME_BYTES { (stem, ext) = (name, ""); }
    let mut room = (MAX_NAME_BYTES - tag.len() - ext.len()).min(stem.len());
    while !stem.is_char_boundary(room) { room -= 1; }
    format!("{}{tag}{ext}", &stem[..room])
}

/// Hands out the names a batch's files are saved under, in the batch's order: a name as it came when no
/// earlier one has its key, else `with_suffix` from " (2)" up until the key is free. Each name's next number
/// is remembered, so 10,000 files of one name take linear time.
#[derive(Default)]
pub struct UniqueNames { taken: HashSet<String>, next: HashMap<String, u32> }

impl UniqueNames {
    pub fn new() -> UniqueNames { UniqueNames::default() }
    /// A name no file may take (the store holding the stream, say).
    pub fn reserve(&mut self, name: &str) { self.taken.insert(name_key(name)); }
    /// The name to save `name` under.
    pub fn add(&mut self, name: &str) -> String {
        let key = name_key(name);
        if self.taken.insert(key.clone()) { return name.to_owned(); }
        let mut n = self.next.get(&key).copied().unwrap_or(2);
        loop {
            let candidate = with_suffix(name, n);
            n += 1;
            if self.taken.insert(name_key(&candidate)) { self.next.insert(key, n); return candidate; }
        }
    }
}

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const S_COUNT: u32 = 19 * V_COUNT * T_COUNT;

/// The full canonical decomposition of `c`, appended to `out`.
fn decompose(c: char, out: &mut Vec<char>) {
    let cp = c as u32;
    if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
        let s = cp - S_BASE;
        let jamo = |v: u32| char::from_u32(v).unwrap_or(c);
        out.push(jamo(L_BASE + s / (V_COUNT * T_COUNT)));
        out.push(jamo(V_BASE + (s % (V_COUNT * T_COUNT)) / T_COUNT));
        if s % T_COUNT != 0 { out.push(jamo(T_BASE + s % T_COUNT)); }
        return;
    }
    if !(0xC0..=0xFFFF).contains(&cp) { out.push(c); return; }
    match DECOMPOSITIONS.binary_search_by_key(&(cp as u16), |e| e.0) {
        Ok(i) => {
            let (_, a, b) = DECOMPOSITIONS[i];
            for part in [a, b] { if part != 0 { decompose(char::from_u32(part as u32).unwrap_or(c), out); } }
        }
        Err(_) => out.push(c),
    }
}

fn combining_class(c: char) -> u8 {
    let cp = c as u32;
    if !(0x300..=0xFFFF).contains(&cp) { return 0; }
    let i = COMBINING_CLASSES.partition_point(|r| (r.1 as u32) < cp);
    match COMBINING_CLASSES.get(i) { Some(&(lo, _, class)) if lo as u32 <= cp => class, _ => 0 }
}

/// Canonical ordering: marks (class > 0) after one another sorted by class, stably.
fn reorder(s: &mut [char]) {
    for i in 1..s.len() {
        let mut j = i;
        let c = combining_class(s[j]);
        if c == 0 { continue; }
        while j > 0 { let p = combining_class(s[j - 1]); if p <= c { break; } s.swap(j - 1, j); j -= 1; }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn equivalent_names_share_a_key() {
        // canonically equivalent or equal in any case (checked against Python's NFD(casefold(NFD(x))))
        for (a, b) in [("Caf\u{e9}", "cafe\u{301}"), ("\u{c5}ngstr\u{f6}m", "\u{212b}ngstro\u{308}m"), ("stra\u{df}e", "STRASSE"), ("\u{1e9e}", "ss"),
                       ("\u{ac00}", "\u{1100}\u{1161}"), ("\u{d55c}\u{ae00}", "\u{1112}\u{1161}\u{11ab}\u{1100}\u{1173}\u{11af}"),
                       ("\u{304c}\u{3063}\u{3053}\u{3046}", "\u{304b}\u{3099}\u{3063}\u{3053}\u{3046}"), ("\u{30d1}\u{30b9}", "\u{30cf}\u{309a}\u{30b9}"),
                       ("\u{1ec7}", "e\u{323}\u{302}"), ("\u{ea}\u{323}", "e\u{323}\u{302}"),
                       ("\u{3a3}\u{399}\u{3a3}\u{3a5}\u{3a6}\u{39f}\u{3a3}", "\u{3c3}\u{3b9}\u{3c3}\u{3c5}\u{3c6}\u{3bf}\u{3c2}"),
                       ("\u{130}stanbul", "i\u{307}stanbul"), ("\u{419}", "\u{438}\u{306}"), ("\u{fb01}le", "FILE"), ("\u{3d0}", "\u{3b2}"),
                       ("\u{212a}", "k"), ("Photo.JPG", "photo.jpg"), (".bashrc", "bashrc"),
                       // coarser than case folding, the safe side: dotless i and long s uppercase to I and S, and
                       // NTFS takes them for one name with i and s
                       ("\u{131}", "i"), ("\u{17f}", "s")] {
            assert_eq!(name_key(a), name_key(b), "{a:?} and {b:?}");
        }
    }
    #[test]
    fn different_names_keep_their_keys() {
        for (a, b) in [("cafe", "caf\u{e9}"), ("resume.pdf", "r\u{e9}sum\u{e9}.pdf"), ("\u{304b}", "\u{304c}"), ("a.txt", "a.text"), ("\u{1100}", "\u{ac00}")] {
            assert_ne!(name_key(a), name_key(b), "{a:?} and {b:?}");
        }
    }
    #[test]
    fn the_tables_are_sorted() {
        assert!(DECOMPOSITIONS.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(COMBINING_CLASSES.windows(2).all(|w| w[0].1 < w[1].0) && COMBINING_CLASSES.iter().all(|r| r.0 <= r.1 && r.2 > 0));
        assert_eq!((combining_class('\u{301}'), combining_class('\u{323}'), combining_class('\u{3099}'), combining_class('a')), (230, 220, 8, 0));
    }
    #[test]
    fn suffixes_go_before_the_extension_within_255_bytes() {
        assert_eq!(with_suffix("photo.jpg", 2), "photo (2).jpg");
        assert_eq!(with_suffix("archive.tar.gz", 3), "archive.tar (3).gz");
        assert_eq!(with_suffix(".profile", 2), ".profile (2)");
        assert_eq!(with_suffix("README", 2), "README (2)");
        let long = format!("{}.jpg", "x".repeat(251));
        assert_eq!(with_suffix(&long, 2), format!("{} (2).jpg", "x".repeat(247)));
        // a cut never splits a character, and the result is a name `safe_name` leaves as it is
        let wide = format!("{}.txt", "\u{6f22}".repeat(83));
        let s = with_suffix(&wide, 10);
        assert!(s.len() <= 255 && s.ends_with(" (10).txt"), "{} bytes: {s}", s.len());
        assert_eq!(super::super::batch::safe_name(&s), s);
        let all_ext = format!("a.{}", "e".repeat(252));
        let s = with_suffix(&all_ext, 2);
        assert!(s.len() <= 255 && s.ends_with(" (2)"), "{s}");
    }
    #[test]
    fn unique_names_number_each_name_on() {
        let mut u = UniqueNames::new();
        u.reserve("batch.lbpart");
        let got: Vec<String> = ["a.jpg", "A.JPG", "a.jpg", "a (2).jpg", "batch.lbpart", "b.jpg"].iter().map(|n| u.add(n)).collect();
        assert_eq!(got, ["a.jpg", "A (2).JPG", "a (3).jpg", "a (2) (2).jpg", "batch (2).lbpart", "b.jpg"]);
        let mut u = UniqueNames::new();
        let t = std::time::Instant::now();
        for _ in 0..10_000 { u.add("same.txt"); }
        assert_eq!(u.add("same.txt"), "same (10001).txt");
        assert!(t.elapsed().as_millis() < 2_000, "{:?}", t.elapsed());
    }
}

